 shift=i%3; options=c['options'][shift:]+c['options'][:shift]
 data={'question':c['q'],'options':options,'answer':options.index(c['options'][0]),'explanation':c['why']}
 out.joinpath('Demo.tsx').write_text(T.replace('__DATA__',json.dumps(data,ensure_ascii=False,indent=2)).replace('__BASE__',jsx(c['base'])).replace('__MARK__',jsx(c['mark'])))
 source='Unverified research starting point: OpenStax Biology 2e, Birds, https://openstax.org/books/biology-2e/pages/29-4-birds; species- or claim-specific citations require independent matching.'
